"""``make gen-types`` step 1: dump JSON Schema for every exported pydantic model.

Step 2 (web/scripts/gen-types.mjs) turns the bundle into TypeScript under
``web/src/types/generated``. Never hand-edit the generated files.
"""

from __future__ import annotations

import json
import sys
from pathlib import Path

from galecore.schemas import SCHEMA_VERSION, json_schemas

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "web" / "src" / "types" / "generated" / "schemas.json"


def bundle() -> dict[str, object]:
    return {
        "$comment": "GENERATED by `make gen-types` from packages/galecore/schemas.py. Do not edit.",
        "schema_version": SCHEMA_VERSION,
        "models": json_schemas(),
    }


def main() -> int:
    OUT.parent.mkdir(parents=True, exist_ok=True)
    text = json.dumps(bundle(), indent=2, ensure_ascii=False, sort_keys=True) + "\n"
    OUT.write_text(text, encoding="utf-8", newline="\n")
    print(f"wrote {OUT.relative_to(ROOT).as_posix()}", file=sys.stderr)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
